const envelopes = $input.all().map(i=>i.json);
const cfg = envelopes.find(x=>x.source==='_contexto')?.data?.[0];
if(!cfg?.today || !cfg.nextWeekStart || !cfg.endWindowDate) throw new Error('Falta contexto: execute o workflow inteiro pelo Teste manual, incluindo Resolver Listas e Merge.');
const TZ=cfg.timezone, today=cfg.today, now=new Date(cfg.nowIso);
const warnings=[...(cfg.listWarnings||[])];
const clean=(v,max=250)=>String(v??'').replace(/[\r\n\t]+/g,' ').trim().slice(0,max);
const norm=v=>clean(v).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const dateKey=v=>new Intl.DateTimeFormat('en-CA',{timeZone:TZ,year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(v));
const clock=v=>new Date(v).toLocaleTimeString('pt-BR',{timeZone:TZ,hour:'2-digit',minute:'2-digit'});
const shortDate=v=>{ const d=String(v||'').slice(0,10);return /^\d{4}-\d{2}-\d{2}$/.test(d)?d.slice(8,10)+'/'+d.slice(5,7):'data inválida'; };
const sourceStatus={};
const expectedSources=['Google Calendar - Semana','Tasks - Minha Rotina','Tasks - Hackathon GH','Tasks - E-Racing','Tasks - Profissional','Sheets - Objetivos Ativos','Clima - Campinas','CoinGecko - Cotações','Notícias - Agência Brasil'];
for(const name of expectedSources){
 const hits=envelopes.filter(x=>x.source===name);
 if(hits.length!==1 || !Array.isArray(hits[0].data)) throw new Error('Fluxo incompleto: falta uma saída única de '+name+'. Execute o workflow inteiro pelo Teste manual.');
}
function rows(name) {
 const all=envelopes.find(x=>x.source===name).data.map(x=>x||{});
 const isError=x=>x.error || x.status==='error' || Number(x.statusCode)>=400 || Number(x.status)>=400 || (x.cod && !['200',200].includes(x.cod)) || x.status?.error_code;
 const bad=all.find(isError);
 if(bad){
  const raw=JSON.stringify(bad);
  let message='erro de consulta; veja a execução desse nó';
  if(/\b401\b|unauthori[sz]ed|invalid.*credential|invalid.*token/i.test(raw))message='401: credencial inválida ou expirada; reconecte essa conta';
  else if(/\b403\b|forbidden|permission/i.test(raw))message='403: acesso negado; confira permissões e APIs habilitadas';
  else if(/\b429\b|rate.?limit|too many/i.test(raw))message='429: limite de consultas; tente novamente depois';
  else if(/timeout|timed.?out|ETIMEDOUT/i.test(raw))message='tempo limite excedido';
  else if(/ENOTFOUND|EAI_AGAIN|ECONNREFUSED|ECONNRESET/i.test(raw))message='falha de rede ou resolução DNS na EC2';
  sourceStatus[name]='error';warnings.push(name+': '+message+'.');return null;
 }
 const valid=all.filter(x=>Object.keys(x).length);
 if(name==='Clima - Campinas' && !Number.isFinite(valid[0]?.current?.temperature_2m)){
  sourceStatus[name]='error';warnings.push(name+': resposta sem temperatura; confira o retorno do serviço.');return null;
 }
 if(name==='CoinGecko - Cotações' && !['bitcoin','solana','ripple','usd-coin'].some(k=>Number.isFinite(valid[0]?.[k]?.brl))){
  sourceStatus[name]='error';warnings.push(name+': resposta sem preços válidos.');return null;
 }
 sourceStatus[name]='ok';return valid;
}
function capped(lines,max=12){return lines.slice(0,max).join('\n')+(lines.length>max?`\n… e mais ${lines.length-max}.`:'');}
const eventRows=rows('Google Calendar - Semana');
let calendar='⚠️ Agenda indisponível.';
if(eventRows) {
 const valid=eventRows.filter(e=>e.start && e.status!=='cancelled')
  .filter(e=>{
    const ok=e.start.dateTime ? Number.isFinite(new Date(e.start.dateTime).getTime()) : /^\d{4}-\d{2}-\d{2}$/.test(e.start.date||'');
    if(!ok)warnings.push('Agenda: evento com data inválida omitido.');return ok;
  })
  .filter(e=>!e.end?.dateTime || new Date(e.end.dateTime)>now)
  .filter(e=>!e.end?.date || e.end.date>today)
  .sort((a,b)=>new Date(a.start.dateTime||a.start.date).getTime()-new Date(b.start.dateTime||b.start.date).getTime());
 const render=e=>e.start.dateTime?`• ${shortDate(dateKey(e.start.dateTime))} ${clock(e.start.dateTime)} — ${clean(e.summary||'Sem título',140)}`:`• ${shortDate(e.start.date)} — ${clean(e.summary||'Sem título',140)} (dia inteiro)`;
 const key=e=>e.start.dateTime?dateKey(e.start.dateTime):e.start.date;
 const current=valid.filter(e=>key(e)<cfg.nextWeekStart);
 const next=valid.filter(e=>key(e)>=cfg.nextWeekStart && key(e)<cfg.endWindowDate);
 calendar=`*Restante desta semana — até ${shortDate(new Date(new Date(cfg.nextWeekStart+'T12:00:00Z').getTime()-86400000).toISOString())}*\n`+(current.length?current.map(render).join('\n'):'Nenhum compromisso restante nesta semana.')+'\n\n*Próxima semana*\n'+(next.length?next.map(render).join('\n'):'Nenhum compromisso na próxima semana.');
}
let totalCurrent=0,totalNext=0,totalLate=0,successfulTaskLists=0;
const taskSections=[];
for(const [key,name,label] of [['rotina','Tasks - Minha Rotina','Minha Rotina'],['hackathon','Tasks - Hackathon GH','Hackathon GH'],['eracing','Tasks - E-Racing','E-Racing'],['profissional','Tasks - Profissional','Profissional']]) {
 const data=rows(name);
 if(!data || !cfg.listIds?.[key] || cfg.listIds[key]==='LISTA_NAO_ENCONTRADA'){ sourceStatus[name]='error'; taskSections.push(`*${label}*\n⚠️ Consulta indisponível; confira a lista e a credencial.`); continue; }
 successfulTaskLists++;
 const active=data.filter(t=>t.title && t.status!=='completed' && !t.completed && !t.deleted && !t.hidden);
 const validDue=t=>/^\d{4}-\d{2}-\d{2}/.test(t.due||'');
 const due=t=>String(t.due).slice(0,10);
 const late=active.filter(t=>validDue(t)&&due(t)<today).sort((a,b)=>due(a).localeCompare(due(b)));
 const order=(a,b)=>due(a).localeCompare(due(b)) || String(a.title).localeCompare(String(b.title),'pt-BR');
 const current=active.filter(t=>validDue(t)&&due(t)>=today&&due(t)<cfg.nextWeekStart).sort(order);
 const next=active.filter(t=>validDue(t)&&due(t)>=cfg.nextWeekStart&&due(t)<cfg.endWindowDate).sort(order);
 const noDue=active.filter(t=>!t.due);
 const future=active.filter(t=>validDue(t)&&due(t)>=cfg.endWindowDate);
 const invalid=active.filter(t=>t.due&&!validDue(t));
 if(invalid.length)warnings.push(`${label}: ${invalid.length} tarefa(s) com data inválida.`);
 totalCurrent+=current.length;totalNext+=next.length;totalLate+=late.length;
 let text=`*${label}*\n`;
 if(late.length) text+='🔴 Atrasadas (mais antigas primeiro):\n'+late.map(t=>`• ${shortDate(t.due)} — ${clean(t.title,160)}`).join('\n')+'\n';
 const renderTask=t=>`• ${due(t)===today?'HOJE':shortDate(t.due)} — ${clean(t.title,160)}`;
 text+='Esta semana:\n'+(current.length?current.map(renderTask).join('\n'):'Nenhuma tarefa restante nesta semana.');
 text+='\nPróxima semana:\n'+(next.length?next.map(renderTask).join('\n'):'Nenhuma tarefa na próxima semana.');
 if(noDue.length)text+='\nSem data:\n'+noDue.map(t=>'• '+clean(t.title,160)).join('\n');
 if(future.length)text+=`\n${future.length} tarefa(s) após a próxima semana, fora deste período.`;
 taskSections.push(text);
}
const objectiveRows=rows('Sheets - Objetivos Ativos');
let objectives='⚠️ Objetivos indisponíveis.';
if(objectiveRows){const active=objectiveRows.filter(o=>o.objetivo&&!['concluido','concluida','feito','feita','completed','cancelado','cancelada','arquivado','arquivada'].includes(norm(o.status)));
 objectives=active.length?capped(active.map(o=>`• ${clean(o.objetivo,180)}${o.prazo?' — prazo: '+clean(o.prazo,30):''}`),8):'Nenhum objetivo ativo.';}
const weatherRows=rows('Clima - Campinas'),weather=weatherRows?.[0];
let weatherText='⚠️ Clima indisponível.';
if(weather){
 const c=weather.current,d=weather.daily||{},idx=(d.time||[]).indexOf(today);
 const labels={0:'céu limpo',1:'predominantemente limpo',2:'parcialmente nublado',3:'nublado',45:'neblina',48:'neblina com geada',51:'garoa leve',53:'garoa',55:'garoa forte',56:'garoa congelante leve',57:'garoa congelante',61:'chuva leve',63:'chuva moderada',65:'chuva forte',66:'chuva congelante leve',67:'chuva congelante',71:'neve leve',73:'neve',75:'neve forte',77:'grãos de neve',80:'pancadas leves',81:'pancadas moderadas',82:'pancadas fortes',85:'pancadas de neve',86:'pancadas fortes de neve',95:'trovoadas',96:'trovoadas com granizo',99:'trovoadas com granizo forte'};
 const num=v=>Number.isFinite(v)?v.toFixed(1):'indisponível';
 weatherText=`${labels[c.weather_code]||'condição não descrita'} • ${num(c.temperature_2m)}°C`;
 if(Number.isFinite(c.apparent_temperature))weatherText+=` (sensação ${num(c.apparent_temperature)}°C)`;
 if(Number.isFinite(c.relative_humidity_2m))weatherText+=`\nUmidade: ${c.relative_humidity_2m}%.`;
 if(idx>=0){
  const min=d.temperature_2m_min?.[idx],max=d.temperature_2m_max?.[idx],pop=d.precipitation_probability_max?.[idx];
  if(Number.isFinite(min)&&Number.isFinite(max))weatherText+=`\nHoje: ${num(min)}–${num(max)}°C.`;
  if(Number.isFinite(pop))weatherText+=` Chance máxima de chuva: ${Math.round(pop)}%.`;
  if(pop>=40)weatherText+='\n☂️ Considere levar guarda-chuva.';
 }
 weatherText+=`\nFonte: Open-Meteo${c.time?' • atualização '+String(c.time).slice(11,16):''}.`;
}
const prices=rows('CoinGecko - Cotações')?.[0];
const money=(v,cur)=>Number.isFinite(v)?v.toLocaleString('pt-BR',{style:'currency',currency:cur}):'indisponível';
let rates='⚠️ Cotações indisponíveis.';
if(prices){const list=[['bitcoin','Bitcoin'],['solana','Solana'],['ripple','XRP'],['usd-coin','USDC']];
 rates=list.map(([key,label])=>{
 const p=prices[key];if(!p || !Number.isFinite(p.brl)){warnings.push(`Cotação ${label}: indisponível.`);return `• ${label}: indisponível.`;}
 const stamp=Number.isFinite(p.last_updated_at)?` (${clock(p.last_updated_at*1000)})`:'';
 if(p.last_updated_at && now.getTime()/1000-p.last_updated_at>3600)warnings.push(`Cotação ${label}: atualização há mais de uma hora.`);
 return `• ${label}: ${money(p.brl,'BRL')} | ${money(p.usd,'USD')}${stamp}`;
 }).join('\n')+'\nUSDC é um criptoativo; não é a cotação oficial do dólar.';}
const newsRows=rows('Notícias - Agência Brasil');
let newsText='⚠️ Notícias indisponíveis.';
if(newsRows){
 const seen=new Set(),cutoff=now.getTime()-24*3600000;
 const articles=newsRows.filter(a=>a.title && /^https?:\/\//.test(a.link||a.url||''))
  .map(a=>({...a,published:new Date(a.isoDate||a.pubDate||a.date||'').getTime(),url:a.link||a.url}))
  .filter(a=>Number.isFinite(a.published)&&a.published>=cutoff&&a.published<=now.getTime()+5*60000)
  .sort((a,b)=>b.published-a.published)
  .filter(a=>!seen.has(a.url)&&(seen.add(a.url),true));
 newsText=articles.length?articles.slice(0,3).map((a,i)=>`${i+1}. ${clean(a.title,220)} — Agência Brasil\n${a.url}`).join('\n\n'):'Nenhuma notícia das últimas 24 horas no feed da Agência Brasil.';
}
const successfulSources=Object.values(sourceStatus).filter(s=>s==='ok').length;
if(!successfulSources)throw new Error('Nenhuma fonte pôde ser consultada. O briefing não foi enviado para evitar informar dados falsos. '+warnings.join(' | '));
const taskSummary=successfulTaskLists ? `${totalLate} atrasada(s), ${totalCurrent} nesta semana e ${totalNext} na próxima${successfulTaskLists<4?` — contagem parcial (${successfulTaskLists}/4 listas)`:''}.` : 'Contagem de tarefas indisponível: nenhuma das quatro listas foi consultada com sucesso.';

const briefing=`🌅 *Bom dia, Cairê!* ${shortDate(today)} • ${clock(now)}\n${taskSummary}\n\n📅 *AGENDA — ESTA SEMANA E PRÓXIMA*\n${calendar}\n\n✅ *TAREFAS — POR VENCIMENTO*\n${taskSections.join('\n\n')}\n\n🌤️ *PREVISÃO — CAMPINAS*\n${weatherText}\n\n🎯 *OBJETIVOS ATIVOS*\n${objectives}\n\n💰 *COTAÇÕES*\n${rates}\n\n📰 *NOTÍCIAS — ÚLTIMAS 24H*\n${newsText}${warnings.length?'\n\n⚠️ *AVISOS*\n'+[...new Set(warnings)].map(w=>'• '+w).join('\n'):''}`;
return [{json:{briefing,recipient:cfg.recipient,warnings:[...new Set(warnings)],diagnostics:{version:'3.0.0',successfulSources,successfulTaskLists,sourceStatus}}}];

const now = $now.setZone('America/Sao_Paulo');
const cfg = {
  timezone: 'America/Sao_Paulo', nowIso: now.toISO(), today: now.toISODate(),
  startDay: now.startOf('day').toISO(),
  weekStart: now.startOf('week').toISODate(), nextWeekStart: now.startOf('week').plus({weeks:1}).toISODate(),
  endWindowDate: now.startOf('week').plus({weeks:2}).toISODate(),
  endWindow: now.startOf('week').plus({weeks:2}).toISO(),
  newsFrom: now.minus({hours:24}).toUTC().toISO(),
  recipient: 'CONFIGURAR_NUMERO_WHATSAPP', city: 'Campinas,BR',
  listNames: {rotina:'Minha Rotina', hackathon:'Grupo de estudos para Hackathon (GH)', eracing:'E-Racing', profissional:'Profissional'},
  fallbackIds: {},
};
const response = $input.first().json;
const norm = v => String(v || '').normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim().toLowerCase();
const lists = Array.isArray(response.items) ? response.items : [];
const listIds={}, listWarnings=[];
for (const [key,title] of Object.entries(cfg.listNames)) {
  const matches = lists.filter(l => norm(l.title) === norm(title));
  if (matches.length===1) listIds[key]=matches[0].id;
  else if ((response.error || !Array.isArray(response.items)) && cfg.fallbackIds[key]) {
    listIds[key]=cfg.fallbackIds[key];
    listWarnings.push(`Não foi possível descobrir listas; ${title} usa o ID do workflow principal.`);
  } else {
    listIds[key]='LISTA_NAO_ENCONTRADA';
    listWarnings.push(matches.length>1 ? `Há listas duplicadas com nome ${title}; selecione o ID em Resolver Listas.` : `Lista não encontrada: ${title}.`);
  }
}
if(response.nextPageToken) listWarnings.push('Há mais de 1000 listas; a descoberta de listas ficou incompleta.');
return [{json:{...cfg,listIds,listWarnings}}];

const input = $input.first().json;
const limit=3000, chunks=[];
let current='';
for(const line of input.briefing.split('\n')) {
  const points=Array.from(line);
  do {
    let part='';
    while(points.length && part.length+points[0].length<=limit) part+=points.shift();
    if(current && current.length+part.length+1>limit){ chunks.push(current);current=''; }
    current+=(current?'\n':'')+part;
  } while(points.length);
}
if(current) chunks.push(current);
return chunks.map((text,i)=>({json:{number:input.recipient,text:chunks.length>1?`[${i+1}/${chunks.length}]\n${text}`:text}}));
